INSERT INTO "products" VALUES ('1', 'Mak Taste Of Cambodia', 'mak-taste-of-cambodia', 'https://res.cloudinary.com/dvwqaa0de/image/upload/v1777312872/Mak_Taste_Of_Cambodia_o6snjt.png', '18.00', 'null', 'A rich and aromatic Cambodian-inspired seasoning blend, Mak Taste of Cambodia brings authentic Khmer flavors with a modern twist. Crafted in the USA using traditional spice profiles, this seasoning is perfect for grilling, marinating, or enhancing everyday dishes. It delivers a bold balance of savory, earthy, and slightly sweet notes that capture the essence of Cambodian street food and home-style cooking. Whether you''re preparing BBQ, stir-fry, or slow-cooked meats, this blend adds deep, unforgettable flavor to every bite.', '250.00', '40', 'Tue Apr 28 2026 17:26:32 GMT-0400 (Eastern Daylight Time)', 'Tue Apr 28 2026 17:26:32 GMT-0400 (Eastern Daylight Time)');

