INSERT INTO "ambassadors" VALUES ('1', 'https://res.cloudinary.com/dvwqaa0de/image/upload/v1777438124/photo_2025-11-24_02-59-02_hcnlih.jpg', 'Cambodia', 'SuSu Cute', 'Heritage Preservationist', 'As a guardian of our ancestral recipes, I am selective. Mak honors the stone carvings of Angkor not just in design, but in the depth of its lemongrass and galangal profile.', 'Whisked into fresh coconut milk for a morning ''Sac Ko Ang'' marinade that tastes like childhood.', 'Wed Apr 29 2026 05:14:26 GMT-0400 (Eastern Daylight Time)', 'Wed Apr 29 2026 05:14:26 GMT-0400 (Eastern Daylight Time)');
